bitflags::bitflags! {
    /// C# `[Flags] enum CoverageMask : u32`.
    /// Used during Calculation of Damage
    /// This data is sent in the priority field of the list (equipped items) portion of the player description event F7B0 - 0013 Og II
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
    pub struct CoverageMask: u32 {
        const Unknown = 0x1;
        const UnderwearUpperLegs = 0x2;
        const UnderwearLowerLegs = 0x4;
        const UnderwearChest = 0x8;
        const UnderwearAbdomen = 0x10;
        const UnderwearUpperArms = 0x20;
        const UnderwearLowerArms = 0x40;
        const OuterwearUpperLegs = 0x100;
        const OuterwearLowerLegs = 0x200;
        const OuterwearChest = 0x400;
        const OuterwearAbdomen = 0x800;
        const OuterwearUpperArms = 0x1000;
        const OuterwearLowerArms = 0x2000;
        const Head = 0x4000;
        const Hands = 0x8000;
        const Feet = 0x10000;
    }
}

/// C# `enum CoverageMaskHelper : u32`.
///
/// 1 C# member(s) share a discriminant with an earlier one, which
/// Rust enums disallow; those are associated consts below.
#[repr(u32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum CoverageMaskHelper {
    Underwear = 0x7e,
    Outerwear = 0x1ff00,
    UnderwearLegs = 0x6,
    UnderwearArms = 0x60,
    OuterwearLegs = 0x300,
    OuterwearArms = 0x3000,
    UnderwearShirt = 0x68,
    Extremities = 0x1c000,
}

impl CoverageMaskHelper {
    /// Alias of [`Self::UnderwearLegs`].
    pub const UnderwearPants: Self = Self::UnderwearLegs;
    /// Decode from the on-disk value. `None` for anything undefined —
    /// a C-style cast would produce a value outside the enum, which is UB.
    pub fn from_raw(v: u32) -> Option<Self> {
        Some(match v {
            0x7e => Self::Underwear,
            0x1ff00 => Self::Outerwear,
            0x6 => Self::UnderwearLegs,
            0x60 => Self::UnderwearArms,
            0x300 => Self::OuterwearLegs,
            0x3000 => Self::OuterwearArms,
            0x68 => Self::UnderwearShirt,
            0x1c000 => Self::Extremities,
            _ => return None,
        })
    }
    /// The on-disk value.
    pub fn to_raw(self) -> u32 {
        self as u32
    }
}

