/// Used to select a data source location.
/// C# `enum SourceSelectionOption : i32`.
#[repr(i32)]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum SourceSelectionOption {
    None = 0x0,
    Github = 0x1,
    LocalDisk = 0x2,
}

impl SourceSelectionOption {
    /// Decode from the on-disk value. `None` for anything undefined —
    /// a C-style cast would produce a value outside the enum, which is UB.
    pub fn from_raw(v: i32) -> Option<Self> {
        Some(match v {
            0x0 => Self::None,
            0x1 => Self::Github,
            0x2 => Self::LocalDisk,
            _ => return None,
        })
    }
    /// The on-disk value.
    pub fn to_raw(self) -> i32 {
        self as i32
    }
}

bitflags::bitflags! {
    /// C# `[Flags] enum SpellBitfield : i32`.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default)]
    pub struct SpellBitfield: i32 {
        const Resistable = 0x1;
        const PKSensitive = 0x2;
        const Beneficial = 0x4;
        const SelfTargeted = 0x8;
        const Reversed = 0x10;
        const NotIndoor = 0x20;
        const NotOutdoor = 0x40;
        const NotResearchable = 0x80;
        const Projectile = 0x100;
        const CreatureSpell = 0x200;
        const ExcludedFromItemDescriptions = 0x400;
        const IgnoresManaConversion = 0x800;
        const NonTrackingProjectile = 0x1000;
        const FellowshipSpell = 0x2000;
        const FastCast = 0x4000;
        const IndoorLongRange = 0x8000;
        const DamageOverTime = 0x10000;
        const UNKNOWN = 0x20000;
    }
}

